    axisGrads: { acuity: 11, calibration: 17, magnanimity: 16, discourse: 12, consistency: 8, reach: 20 },
    tierProfile: { forum: 0.65, spark: 0.3, echo: 0.03, fog: 0.01, heat: 0.01, stance: 0, breach: 0 },
