    axisGrads: { acuity: 13, calibration: 19, magnanimity: 21, discourse: 18, consistency: 12, reach: 14 },
    tierProfile: { forum: 0.62, spark: 0.2, echo: 0.05, fog: 0.04, heat: 0.07, stance: 0.02, breach: 0 },
