    axisGrads: { acuity: 19, calibration: 11, magnanimity: 9, discourse: 10, consistency: 18, reach: 10 },
    tierProfile: { forum: 0.78, spark: 0.18, echo: 0.02, fog: 0.01, heat: 0.01, stance: 0, breach: 0 },
