    axisGrads: { acuity: 14, calibration: 22, magnanimity: 13, discourse: 13, consistency: 11, reach: 12 },
    tierProfile: { forum: 0.85, spark: 0.12, echo: 0.02, fog: 0.01, heat: 0, stance: 0, breach: 0 },
